// @name Transit departures (Boston, USA)
// @background #0f172a
// @refresh 60
// The next MBTA departures from one or two stops in and around Boston, as a
// station board: subway, bus, commuter rail and ferry, each line in its
// color, where it goes and the minutes until it leaves. Live predictions
// from the MBTA's own API (no key needed), its timetable where nothing is
// predicted yet, delays and cancellations. The last good departures are kept
// on disk (the private `board` field), and an error says what went wrong.
import { due, loadBoard, stopOf } from './board'
import { refreshStops } from './json'
import { mbta } from './mbta'
import { drawBoard, setupCard } from './ui'

const TITLE = 'Transit departures'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const stops = [stopOf(app.state.stop), stopOf(app.state.stop2)].filter((stop) => stop.query)
  if (!stops.length) {
    return setupCard(app, context, TITLE, 'Add a stop in the scene settings: its MBTA stop id, from the address of its page on mbta.com/stops (place-pktrm is Park Street).')
  }
  const queries = stops.map((stop) => stop.query)
  const key = queries.join('/')
  const now = Date.now()
  let board = loadBoard(app, key)
  if (due(board, now)) board = refreshStops(key, board, now, queries, (query) => mbta(query, now))
  return drawBoard(app, context, { provider: 'MBTA', title: TITLE, labels: stops.map((stop) => stop.label), queries, board })
}

