// The MBTA's API (api-v3.mbta.com): predictions, which are live, and the
// timetable for one stop or station, a few ids with commas ("place-pktrm",
// "1123"). Without a key it allows 20 requests a minute: one a stop here,
// two where the predictions do not fill a board.
import { hex, type Departure, type Stop } from './board'
import { getJson, when } from './json'

const enc = encodeURIComponent

// The hour and minute it is in Boston now, as MBTA's timetable counts them.
export function bostonTime(now: number): { hour: number; text: string } {
  let offset = -5 * 3600
  try {
    const zone = typeof frameos.timeZone === 'function' ? frameos.timeZone('America/New_York') : null
    const changes = zone?.changes || []
    for (let i = 0; i + 1 < changes.length; i += 2) {
      if (changes[i] * 1000 <= now) offset = changes[i + 1]
    }
    if (!changes.length) {
      // No zone data: daylight time from the second Sunday of March to the first of November.
      const y = new Date(now).getUTCFullYear()
      const sunday = (month: number, nth: number) => {
        const first = new Date(Date.UTC(y, month, 1)).getUTCDay()
        return Date.UTC(y, month, 1 + ((7 - first) % 7) + (nth - 1) * 7, 7)
      }
      if (now >= sunday(2, 2) && now < sunday(10, 1)) offset = -4 * 3600
    }
  } catch (e) {
    // keep the standard offset
  }
  const local = new Date(now + offset * 1000)
  const hour = local.getUTCHours()
  return { hour, text: `${String(hour).padStart(2, '0')}:${String(local.getUTCMinutes()).padStart(2, '0')}` }
}

function lineOf(route: any): { label: string; color: string; text: string } {
  const a = route?.attributes || {}
  let label = String(a.short_name || '')
  if (a.type === 2) label = 'CR'
  else if (a.type === 4) label = 'Ferry'
  else if (!label) label = String(a.long_name || route?.id || '').replace(/ Line$/, '').replace(/ Trolley$/, '')
  return { label, color: hex(a.color), text: hex(a.text_color) }
}

const row = (line: { label: string; color: string; text: string }, to: string, at: number, live: boolean, delay: number | null, gone: boolean, where: string): Departure => ({
  line: line.label, color: line.color, text: line.text, to, at, live, delay, gone, where,
})

export function mbta(stop: string, now: number): Stop {
  const ids = stop.split(',').map((s) => s.trim()).filter(Boolean).join(',')
  const base = 'https://api-v3.mbta.com'
  const shared = `&fields%5Btrip%5D=headsign&fields%5Broute%5D=color,text_color,short_name,long_name,type&fields%5Bstop%5D=name,platform_code`
  // Sorted by departure, the trains that end here (no departure) come first:
  // 60 leaves room for a terminal's (South Station's are half of them).
  const predictions = getJson(
    `${base}/predictions?filter%5Bstop%5D=${enc(ids)}&sort=departure_time&page%5Blimit%5D=60&include=trip,route,stop,schedule${shared}` +
      `&fields%5Bprediction%5D=departure_time,schedule_relationship&fields%5Bschedule%5D=departure_time`,
  )
  const included: Record<string, any> = {}
  const keep = (doc: any) => {
    for (const item of doc?.included || []) included[`${item.type}/${item.id}`] = item
  }
  keep(predictions)
  const rel = (item: any, name: string) => {
    const data = item?.relationships?.[name]?.data
    return data ? included[`${data.type}/${data.id}`] : null
  }
  const list: Departure[] = []
  const trips: Record<string, boolean> = {}
  // The last live departure of each line and destination: the timetable
  // says nothing new before it (the subway's timetable is only a pattern).
  const liveUntil: Record<string, number> = {}
  let name = ''
  const where = (item: any, route: any) => {
    const s = rel(item, 'stop')
    if (!name && s?.attributes?.name) name = s.attributes.name
    const code = s?.attributes?.platform_code
    return route?.attributes?.type === 2 && code ? `Track ${code}` : ''
  }
  for (const p of predictions?.data || []) {
    const a = p.attributes || {}
    const route = rel(p, 'route')
    const planned = when(rel(p, 'schedule')?.attributes?.departure_time)
    const gone = a.schedule_relationship === 'CANCELLED' || a.schedule_relationship === 'SKIPPED'
    // No departure time: the trip ends here, or it does not stop.
    const at = gone ? planned : when(a.departure_time)
    if (!(at > 0)) continue
    const line = lineOf(route)
    const to = rel(p, 'trip')?.attributes?.headsign || ''
    list.push(row(line, to, at, !gone, !gone && planned > 0 ? Math.round((at - planned) / 1000) : null, gone, where(p, route)))
    if (p.relationships?.trip?.data?.id) trips[p.relationships.trip.data.id] = true
    if (!gone) liveUntil[`${line.label}|${to}`] = Math.max(liveUntil[`${line.label}|${to}`] || 0, at)
  }
  // The timetable for what has no prediction yet (a bus later today), by
  // Boston's clock, only when the predictions do not fill a board. After
  // midnight the service day is yesterday's, and the predictions alone show.
  const boston = bostonTime(now)
  if (boston.hour >= 3 && list.filter((d) => !d.gone).length < 10) {
    const schedules = getJson(
      `${base}/schedules?filter%5Bstop%5D=${enc(ids)}&filter%5Bmin_time%5D=${boston.text}&sort=departure_time&page%5Blimit%5D=20&include=trip,route,stop${shared}` +
        `&fields%5Bschedule%5D=departure_time`,
    )
    keep(schedules)
    for (const s of schedules?.data || []) {
      const tripId = s.relationships?.trip?.data?.id
      if (tripId && trips[tripId]) continue
      const at = when(s.attributes?.departure_time)
      if (!(at > 0)) continue
      const route = rel(s, 'route')
      const line = lineOf(route)
      const to = rel(s, 'trip')?.attributes?.headsign || ''
      if (at <= (liveUntil[`${line.label}|${to}`] || 0)) continue
      list.push(row(line, to, at, false, null, false, where(s, route)))
    }
  }
  if (!name) {
    // Nothing coming: the stop's own name.
    const first = ids.split(',')[0]
    try {
      name = getJson(`${base}/stops/${enc(first)}?fields%5Bstop%5D=name`)?.data?.attributes?.name || first
    } catch (e) {
      if (String((e as any)?.message).indexOf('HTTP 404') >= 0) throw new Error(`no stop with the id ${first}`)
      name = first
    }
  }
  list.sort((x, y) => x.at - y.at)
  return { name, list }
}

