import { get } from './app'
import { delayText, INKS, nearestInk, upcoming, whenText } from './board'
import { bostonTime, mbta } from './mbta'

// Saturday 28 November 2026, 15:00 UTC (10:00 in Boston).
const NOW = Date.UTC(2026, 10, 28, 15, 0, 0)
const MIN = 60 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// Every string in a JSX tree, to see what a render says.
function textOf(node: any): string {
  if (node === null || node === undefined || node === false || node === true) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textOf).join(' ')
  if (typeof node.type === 'function') return textOf(node.type(node.props || {}))
  return textOf(node.props?.children)
}

// The MBTA's answers, shaped as api-v3.mbta.com sends them (JSON:API).
const route = (id: string, color: string, text: string, short: string, long: string, type: number) => ({
  type: 'route', id, attributes: { color, text_color: text, short_name: short, long_name: long, type },
})
const rel = (type: string, id: string | null) => ({ data: id ? { type, id } : null })
const prediction = (id: string, departure: string | null, sr: string | null, routeId: string, trip: string, schedule: string | null) => ({
  type: 'prediction', id,
  attributes: { departure_time: departure, schedule_relationship: sr },
  relationships: { route: rel('route', routeId), trip: rel('trip', trip), stop: rel('stop', '70075'), schedule: rel('schedule', schedule), vehicle: rel('vehicle', null) },
})
const schedule = (id: string, departure: string | null, routeId: string, trip: string, stop = '1123') => ({
  type: 'schedule', id, attributes: { departure_time: departure },
  relationships: { route: rel('route', routeId), trip: rel('trip', trip), stop: rel('stop', stop) },
})
const PREDICTIONS = {
  data: [
    // Sorted by departure, the canceled and the terminating come first.
    prediction('p3', null, 'CANCELLED', 'Red', 't3', 's3'),
    prediction('p2', null, null, 'Red', 't2', 's2'),
    prediction('p1', '2026-11-28T10:04:00-05:00', null, 'Red', 't1', 's1'),
  ],
  included: [
    route('Red', 'DA291C', 'FFFFFF', '', 'Red Line', 1),
    { type: 'trip', id: 't1', attributes: { headsign: 'Alewife' } },
    { type: 'trip', id: 't3', attributes: { headsign: 'Ashmont' } },
    { type: 'stop', id: '70075', attributes: { name: 'Park Street', platform_code: null } },
    { type: 'schedule', id: 's1', attributes: { departure_time: '2026-11-28T10:02:00-05:00' } },
    { type: 'schedule', id: 's3', attributes: { departure_time: '2026-11-28T10:20:00-05:00' } },
  ],
}
const SCHEDULES = {
  data: [
    schedule('s12', '2026-11-28T10:03:00-05:00', 'Red', 't12'),
    schedule('s1', '2026-11-28T10:02:00-05:00', 'Red', 't1'),
    schedule('s10', '2026-11-28T10:30:00-05:00', '47', 't10'),
    schedule('s20', '2026-11-28T10:40:00-05:00', 'CR-Providence', 't20', 'NEC-2287-03'),
  ],
  included: [
    route('47', 'FFC72C', '000000', '47', 'Central Square - Broadway', 3),
    route('Red', 'DA291C', 'FFFFFF', '', 'Red Line', 1),
    route('CR-Providence', '80276C', 'FFFFFF', '', 'Providence/Stoughton Line', 2),
    { type: 'trip', id: 't10', attributes: { headsign: 'Broadway Station' } },
    { type: 'trip', id: 't12', attributes: { headsign: 'Alewife' } },
    { type: 'trip', id: 't20', attributes: { headsign: 'Providence' } },
    { type: 'stop', id: 'NEC-2287-03', attributes: { name: 'South Station', platform_code: '3' } },
  ],
}

describe('the MBTA', () => {
  it('reads predictions with their delays and cancellations, and the timetable around them', () => {
    const http = mock.httpRequest((url: string) => {
      if (url.indexOf('/predictions?') > 0) return mock.json(PREDICTIONS)
      if (url.indexOf('/schedules?') > 0) return mock.json(SCHEDULES)
      return mock.json({}, 404)
    })
    const stop = mbta('place-pktrm', NOW)
    expect(stop.name).toBe('Park Street')
    expect(stop.list.map((d) => [d.line, d.color, d.text, d.to, (d.at - NOW) / MIN, d.live, d.delay, d.gone, d.where])).toEqual([
      // Live, two minutes late; the timetable's 10:03 to Alewife says nothing new before it.
      ['Red', 'DA291C', 'FFFFFF', 'Alewife', 4, true, 120, false, ''],
      ['Red', 'DA291C', 'FFFFFF', 'Ashmont', 20, false, null, true, ''],
      ['47', 'FFC72C', '000000', 'Broadway Station', 30, false, null, false, ''],
      ['CR', '80276C', 'FFFFFF', 'Providence', 40, false, null, false, 'Track 3'],
    ])
    // The timetable from Boston's 10:00, whatever the frame's own zone.
    const asked = String(http.calls[1][0])
    expect(asked).toContain('filter%5Bmin_time%5D=10:00')
    expect(asked).toContain('filter%5Bstop%5D=place-pktrm')
    expect(bostonTime(Date.UTC(2026, 6, 1, 15, 0, 0)).text).toBe('11:00')
  })

  it('asks for no timetable where the predictions fill a board', () => {
    const many = { data: Array.from({ length: 12 }, (_, i) => prediction(`p${i}`, `2026-11-28T10:${String(10 + i)}:00-05:00`, null, 'Red', `t${i}`, null)), included: PREDICTIONS.included }
    const http = mock.httpRequest(() => mock.json(many))
    expect(mbta('place-pktrm', NOW).list.length).toBe(12)
    expect(http.calls.length).toBe(1)
  })

  it('says when there is no such stop', () => {
    mock.httpRequest((url: string) => (url.indexOf('/stops/') > 0 ? mock.json({ errors: [] }, 404) : mock.json({ data: [], included: [] })))
    expect(() => mbta('place-nowhere', NOW)).toThrow('no stop with the id place-nowhere')
  })
})

const departure = (minutes: number) => ({ line: 'Red', color: 'DA291C', text: 'FFFFFF', to: 'Alewife', at: NOW + minutes * MIN, live: true, delay: null, gone: false, where: '' })

describe('the scene', () => {
  it('keeps the last good departures when the MBTA fails, and says so', () => {
    mock.httpRequest(() => mock.response(503, 'down'))
    const kept = { key: 'place-pktrm', at: NOW - 5 * MIN, tried: NOW - 5 * MIN, error: '', stops: [{ name: 'Park Street', list: [departure(-1), departure(3), departure(9)] }] }
    const app = makeApp({ state: { stop: 'place-pktrm', board: kept } })
    const tree = at(NOW, () => get(app, makeContext()))
    expect(app.state.board.error).toBe('HTTP 503')
    expect(app.state.board.stops[0].list.length).toBe(3)
    const said = textOf(tree)
    expect(said).toContain('MBTA: HTTP 503.')
    expect(said).toContain('Park Street')
    // The one that left is gone; the others count down from the clock.
    expect(said.split('Alewife').length - 1).toBe(2)
  })

  it('asks again only after the gap, unless the footer is tapped', () => {
    const http = mock.httpRequest(() => mock.json({ data: [], included: [] }))
    const app = makeApp({ state: { stop: 'Home = place-pktrm' } })
    at(NOW, () => get(app, makeContext()))
    const first = http.calls.length
    expect(first).toBeGreaterThan(0)
    at(NOW + 10 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(first)
    frameos.remember('force', true)
    const tree = at(NOW + 12 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBeGreaterThan(first)
    // A name of your own, and nothing coming.
    expect(textOf(tree)).toContain('Home')
    expect(textOf(tree)).toContain('No departures coming up')
  })

  it('asks for a stop', () => {
    const app = makeApp({ state: { stop: '', stop2: '' } })
    expect(textOf(get(app, makeContext()))).toContain('Add a stop in the scene settings: its MBTA stop id')
  })
})

describe('the board', () => {
  it('counts down, and says delays and lines as each panel shows them', () => {
    expect(whenText(NOW + 20 * 1000, NOW, false)).toEqual({ big: 'Now', unit: '' })
    expect(whenText(NOW + 4.9 * MIN, NOW, false)).toEqual({ big: '4', unit: 'min' })
    expect(whenText(NOW + 75 * MIN, NOW, true).big).toMatch(/^\d{1,2}:\d\d (am|pm)$/)
    expect([delayText(130), delayText(-61), delayText(20), delayText(null)]).toEqual(['+2', '-1', '', ''])
    expect([nearestInk('DA291C'), nearestInk('FFC72C'), nearestInk('00843D'), nearestInk('003DA5'), nearestInk('7C878E')]).toEqual([
      INKS.red, INKS.yellow, INKS.green, INKS.blue, INKS.black,
    ])
  })

  it('leaves out what is gone, what cannot be caught on foot, and other lines', () => {
    const list = [-2, 3, 8, 15].map((m, i) => ({ ...departure(m), line: i % 2 ? '47' : 'Red' }))
    expect(upcoming(list, NOW, 0, []).map((d) => (d.at - NOW) / MIN)).toEqual([3, 8, 15])
    expect(upcoming(list, NOW, 5, []).map((d) => (d.at - NOW) / MIN)).toEqual([8, 15])
    expect(upcoming(list, NOW, 0, ['red']).map((d) => (d.at - NOW) / MIN)).toEqual([8])
  })
})
